package com.bank.rds;

import java.util.logging.*;

public class RdsDemo {
    private static final Logger log = Logger.getLogger("RDS");

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        RdsInstance ledger = new RdsInstance("nbi-ledger", true /*multiAz*/, 2 /*readReplicas*/, 7 /*backupDays*/);
        DbOperations ops = new DbOperations(ledger);

        log.info(() -> "Primary endpoint: " + ledger.endpoint());
        log.info(() -> "Writes go to primary and synchronous standby (both AZs)");

        log.severe(() -> "Primary AZ failure detected!");
        String afterFailover = ops.failover();
        log.info(() -> "Automatic Multi-AZ failover complete -> " + afterFailover
                + " (same endpoint, ~90s, no app change)");

        log.info(() -> "Month-end report routed to read replica: " + ops.routeReadToReplica());
        log.info(() -> "Point-in-time restore available: " + ops.pointInTimeRestore("2026-10-29 01:00:00"));
    }
}

// ─── Would be in DbOperations.java ───
class DbOperations {
    private final RdsInstance rds;
    DbOperations(RdsInstance rds) { this.rds = rds; }

    // RDS promotes the synchronous standby automatically; endpoint is unchanged.
    String failover() {
        rds.promoteStandby();
        return "promoted standby in another AZ as new primary";
    }

    String routeReadToReplica() {
        if (rds.readReplicas() == 0) return "no replica — report would hit primary";
        return "replica-1 (async copy) served the report, primary untouched";
    }

    String pointInTimeRestore(String timestamp) {
        return "restored to " + timestamp + " from continuous backups (retention "
                + rds.backupRetentionDays() + " days)";
    }
}

// ─── Would be in RdsInstance.java ───
class RdsInstance {
    private final String id;
    private final boolean multiAz;
    private final int readReplicas;
    private final int backupRetentionDays;
    private boolean standbyPromoted = false;

    RdsInstance(String id, boolean multiAz, int readReplicas, int backupRetentionDays) {
        this.id = id; this.multiAz = multiAz;
        this.readReplicas = readReplicas; this.backupRetentionDays = backupRetentionDays;
    }
    String endpoint() { return id + ".abcdef.ap-south-1.rds.amazonaws.com:5432"; }
    boolean multiAz() { return multiAz; }
    int readReplicas() { return readReplicas; }
    int backupRetentionDays() { return backupRetentionDays; }
    void promoteStandby() { this.standbyPromoted = true; }
    boolean standbyPromoted() { return standbyPromoted; }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                r.getMillis(), r.getLevel(), r.getMessage());
    }
}
